-- D-04 made lighter: FSQM-007 and FRM-015 (drafts) rewritten the day they were drafted (owner, 2026-10-05).
--
-- The owner read the first draft (20261005000005) and said it would take a full-time person to track
-- changes. That reading was right: 54 lines, a 20-field form, FRM-015 for eight kinds of change, and a handover
-- record for every change of staff - at a site where a real change happens a few times a year.
-- The four clauses ask for less, and the rewrite keeps exactly that:
--   2.2.1.2  validated or justified BEFORE the change; the reason documented; communicated
--   2.3.1.4  the manufacturing process reviewed, not only the recipe
--   2.3.1.5  process flows that prevent cross-contamination
--   2.1.1.7  the system keeps running when people or the organization change
-- What changed:
--   - FRM-015 is for three kinds of change only: product or recipe, process step or limit, equipment.
--   - A changed procedure, cleaning method, chemical or layout is recorded by revising its document; the
--     reason is in that revision history, which SOP-2.2.3 already requires.
--   - A change of people is a line on that month's FRM-009. No handover form.
--   - FSQM-007: 54 -> 29 procedure lines. FRM-015: 20 -> 12 fields. FRM-015 has no entries.
-- Both documents are replaced whole. Guarded on both md5s as pushed (attachments excluded).

begin;

do $guard$
declare h text;
begin
  select md5((content - 'attachments')::text) into h from public.sop_documents where sop_number = 'FSQM-007' and status = 'draft';
  if h is distinct from '62a6ba6f15c8c65356bdd757647b9574' then raise exception 'FSQM-007 is not the draft that was reviewed (md5 %).', h; end if;
  select md5((content - 'attachments')::text) into h from public.sop_documents where sop_number = 'FRM-015' and status = 'draft';
  if h is distinct from '89b356fe419f18d06668eb6f5e369221' then raise exception 'FRM-015 is not the draft that was reviewed (md5 %).', h; end if;
  if exists (select 1 from public.sop_document_responses r join public.sop_documents d on d.id = r.document_id where d.sop_number = 'FRM-015') then
    raise exception 'FRM-015 has entries; its fields cannot be replaced without a look first.';
  end if;
  if (select count(distinct sop_number) from public.sop_documents
       where sop_number in ('FSQM-004', 'FSQM-005', 'FSQM-016', 'FSQM-017', 'FSQM-027', 'SOP-2.2.3', 'SOP-2.3.1', 'SOP-2.9', 'FRM-001', 'FRM-005', 'FRM-007', 'FRM-009', 'FRM-202', 'FRM-207', 'FRM-601') and status in ('active', 'draft')) <> 15 then
    raise exception 'a document FSQM-007 names is missing.';
  end if;
end $guard$;

update public.sop_documents d
   set content = case when d.content ? 'attachments' then $q${"purpose": "This program states how Adventure Bakery makes a change without losing control of food safety: the changes that matter are assessed and approved before they take effect, the reason is recorded, and the people affected are told.", "scope": "Changes to products, processes, equipment, documents, people and the organization, on the whole site.", "definitions": "Change: anything new or different that could affect the safety of the product or the running of the SQF System.\nAssessment: working out, before the change, what it touches and what is needed to keep the product safe.", "responsibility": "Senior Site Management - approves a change before it takes effect, and keeps the SQF System running when people change.\nSQF Practitioner - assesses the change, revises what it touches, and sees that staff are told and trained. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nAll staff - do not change a recipe, a process, a limit or equipment on their own; tell the SQF Practitioner when a change is needed.", "procedure": ["When a change record is needed", "• FRM-015 is filled in for three kinds of change only, because these are the ones that can change whether the product is safe:", "◦ a new product, or a change to a product's recipe;", "◦ a change to a process step, a time, a temperature or another limit;", "◦ new or modified equipment that touches the product.", "• Every other change is recorded where it already goes, and nowhere else:", "◦ a label - FRM-601; a new supplier - FRM-202; a new material, or a different brand of one already used - FRM-207;", "◦ a change that comes out of a corrective action - the FRM-007 that raised it;", "◦ a change to a procedure, a cleaning method, a chemical or the layout of the site - the document that describes it is revised, and the reason is written in its revision history (SOP-2.2.3).", "• Replacing a part or a material with the same one - same maker, same model or product - is not a change.", "The rule", "• A change is assessed by the SQF Practitioner and approved by Senior Site Management before it takes effect. The reason is written down, and the change is shown to be safe first: by a trial, a measurement, the maker's specification, or a regulatory standard (SQF 2.2.1.2; FSQM-017 Part 4).", "What the assessment looks at", "• The process, not only the recipe: each step the change touches, the equipment, the times and temperatures, and the cleaning. A trial run shows the product can be made; the assessment shows it can be made safely (SQF 2.3.1.4).", "• Five questions, answered on FRM-015:", "◦ Does it change a hazard, a CCP or a limit in the food safety plan (FSQM-016)? If so, the plan is revised and validated first.", "◦ Is the process flow still true? It must still keep unbaked product from baked, and a nut product from a product without that nut (FSQM-027). A changed flow is walked on the floor before it is used (SQF 2.3.1.5).", "◦ Does it change the allergens or the label?", "◦ Does a specification, a cleaning procedure or another document need revising?", "◦ Who has to be told or trained before it starts?", "• Everyone the change affects is told before it takes effect. Where a document changes, it is revised under SOP-2.2.3 and staff are trained on it before they use it (SOP-2.9).", "When people change", "• Senior Site Management keeps the SQF System running when people or the organization change (SQF 2.1.1.7). Every key position already has a named cover (FSQM-004).", "• When a person leaves, joins or changes position, Senior Site Management gives their food safety duties to a named person the same day, the new holder is trained before working alone (SOP-2.9), and the Team Portal access and keys of the person leaving are taken back. It is noted in that month's update on FRM-009. No other record is needed.", "• A change of SQF Practitioner or substitute is recorded on FRM-005.", "The yearly review", "• The annual management review (FSQM-005, FRM-001) looks at the changes made in the year and asks whether the food safety plan, the programs and the documents are still right (SQF 2.2.1.2).", "Records", "• FRM-015 records are kept as SOP-2.2.3 requires."], "form_references": "FRM-015 - Change Assessment Record\nFRM-601 - Label Review & Approval Form\nFRM-202 - Supplier Approval & Evaluation Record\nFRM-207 - Material Specification Register\nFRM-007 - Corrective & Preventive Action (CAPA) Report\nFRM-005 - SQF Practitioner Designation Record\nFRM-009 - Monthly SQF Update Record\nFRM-001 - Management Review Record", "records": "• FRM-015 - one per new product, recipe change, process change or equipment change\n• The revision history of a changed document\n• FRM-009 - changes of people\n• FRM-001 - the yearly review", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.1.1.7, 2.2.1.2, 2.3.1.4, 2.3.1.5.\n\nFSQM-017 Validation and Verification Program - Part 4, the rule that a change is assessed before it takes effect.\nFSQM-016 Food Safety Plan (HACCP); FSQM-027 Allergen Management Program.\nFSQM-005 Management Review Program; FSQM-004 Organizational Structure and Responsibilities.\nSOP-2.3.1 New Product and Specification Process; SOP-2.2.3 Document and Record Control Program; SOP-2.9 Training & Recordkeeping.", "revision_history": "New - 2026-10-05 - DRAFT under D-04, for the Minor findings against 2.1.1.7, 2.2.1.2, 2.3.1.4 and 2.3.1.5. The site had no change management procedure; SOP-2.3.1 pointed at a \"Management of Change Procedure\" that did not exist.\n\nMADE LIGHTER THE SAME DAY (owner, 2026-10-05). The first draft ran to 54 lines and a 20-field form, used FRM-015 for eight kinds of change, and added a handover record for every change of staff. The owner's reading: it would take a full-time person to keep up. The clauses ask for less - a change validated or justified before it is made with the reason recorded (2.2.1.2), the process reviewed and not only the recipe (2.3.1.4), process flows that prevent cross-contamination (2.3.1.5), and a system that keeps running when people change (2.1.1.7). So: FRM-015 is for three kinds of change only; a changed document carries its own reason in its revision history; a change of people is a line on FRM-009; the form went from 20 fields to 12.\n\nBUILT ON WHAT EXISTS: FSQM-017 Part 4 (assess before the change), FSQM-004 (a cover for every key position), FSQM-005 and FRM-001 (the yearly review).\n\nNo verification schedule row: a change is assessed when it happens.\n\nAT ISSUE: revise FSQM-017 Part 4 to name FSQM-007 and FRM-015 in place of its interim rule; revise SOP-2.3.1 so that \"the Management of Change Procedure\" reads FSQM-007.\n\nTO CONFIRM BEFORE ISSUE: the first real change recorded on FRM-015."}$q$::jsonb || jsonb_build_object('attachments', d.content->'attachments') else $q${"purpose": "This program states how Adventure Bakery makes a change without losing control of food safety: the changes that matter are assessed and approved before they take effect, the reason is recorded, and the people affected are told.", "scope": "Changes to products, processes, equipment, documents, people and the organization, on the whole site.", "definitions": "Change: anything new or different that could affect the safety of the product or the running of the SQF System.\nAssessment: working out, before the change, what it touches and what is needed to keep the product safe.", "responsibility": "Senior Site Management - approves a change before it takes effect, and keeps the SQF System running when people change.\nSQF Practitioner - assesses the change, revises what it touches, and sees that staff are told and trained. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nAll staff - do not change a recipe, a process, a limit or equipment on their own; tell the SQF Practitioner when a change is needed.", "procedure": ["When a change record is needed", "• FRM-015 is filled in for three kinds of change only, because these are the ones that can change whether the product is safe:", "◦ a new product, or a change to a product's recipe;", "◦ a change to a process step, a time, a temperature or another limit;", "◦ new or modified equipment that touches the product.", "• Every other change is recorded where it already goes, and nowhere else:", "◦ a label - FRM-601; a new supplier - FRM-202; a new material, or a different brand of one already used - FRM-207;", "◦ a change that comes out of a corrective action - the FRM-007 that raised it;", "◦ a change to a procedure, a cleaning method, a chemical or the layout of the site - the document that describes it is revised, and the reason is written in its revision history (SOP-2.2.3).", "• Replacing a part or a material with the same one - same maker, same model or product - is not a change.", "The rule", "• A change is assessed by the SQF Practitioner and approved by Senior Site Management before it takes effect. The reason is written down, and the change is shown to be safe first: by a trial, a measurement, the maker's specification, or a regulatory standard (SQF 2.2.1.2; FSQM-017 Part 4).", "What the assessment looks at", "• The process, not only the recipe: each step the change touches, the equipment, the times and temperatures, and the cleaning. A trial run shows the product can be made; the assessment shows it can be made safely (SQF 2.3.1.4).", "• Five questions, answered on FRM-015:", "◦ Does it change a hazard, a CCP or a limit in the food safety plan (FSQM-016)? If so, the plan is revised and validated first.", "◦ Is the process flow still true? It must still keep unbaked product from baked, and a nut product from a product without that nut (FSQM-027). A changed flow is walked on the floor before it is used (SQF 2.3.1.5).", "◦ Does it change the allergens or the label?", "◦ Does a specification, a cleaning procedure or another document need revising?", "◦ Who has to be told or trained before it starts?", "• Everyone the change affects is told before it takes effect. Where a document changes, it is revised under SOP-2.2.3 and staff are trained on it before they use it (SOP-2.9).", "When people change", "• Senior Site Management keeps the SQF System running when people or the organization change (SQF 2.1.1.7). Every key position already has a named cover (FSQM-004).", "• When a person leaves, joins or changes position, Senior Site Management gives their food safety duties to a named person the same day, the new holder is trained before working alone (SOP-2.9), and the Team Portal access and keys of the person leaving are taken back. It is noted in that month's update on FRM-009. No other record is needed.", "• A change of SQF Practitioner or substitute is recorded on FRM-005.", "The yearly review", "• The annual management review (FSQM-005, FRM-001) looks at the changes made in the year and asks whether the food safety plan, the programs and the documents are still right (SQF 2.2.1.2).", "Records", "• FRM-015 records are kept as SOP-2.2.3 requires."], "form_references": "FRM-015 - Change Assessment Record\nFRM-601 - Label Review & Approval Form\nFRM-202 - Supplier Approval & Evaluation Record\nFRM-207 - Material Specification Register\nFRM-007 - Corrective & Preventive Action (CAPA) Report\nFRM-005 - SQF Practitioner Designation Record\nFRM-009 - Monthly SQF Update Record\nFRM-001 - Management Review Record", "records": "• FRM-015 - one per new product, recipe change, process change or equipment change\n• The revision history of a changed document\n• FRM-009 - changes of people\n• FRM-001 - the yearly review", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.1.1.7, 2.2.1.2, 2.3.1.4, 2.3.1.5.\n\nFSQM-017 Validation and Verification Program - Part 4, the rule that a change is assessed before it takes effect.\nFSQM-016 Food Safety Plan (HACCP); FSQM-027 Allergen Management Program.\nFSQM-005 Management Review Program; FSQM-004 Organizational Structure and Responsibilities.\nSOP-2.3.1 New Product and Specification Process; SOP-2.2.3 Document and Record Control Program; SOP-2.9 Training & Recordkeeping.", "revision_history": "New - 2026-10-05 - DRAFT under D-04, for the Minor findings against 2.1.1.7, 2.2.1.2, 2.3.1.4 and 2.3.1.5. The site had no change management procedure; SOP-2.3.1 pointed at a \"Management of Change Procedure\" that did not exist.\n\nMADE LIGHTER THE SAME DAY (owner, 2026-10-05). The first draft ran to 54 lines and a 20-field form, used FRM-015 for eight kinds of change, and added a handover record for every change of staff. The owner's reading: it would take a full-time person to keep up. The clauses ask for less - a change validated or justified before it is made with the reason recorded (2.2.1.2), the process reviewed and not only the recipe (2.3.1.4), process flows that prevent cross-contamination (2.3.1.5), and a system that keeps running when people change (2.1.1.7). So: FRM-015 is for three kinds of change only; a changed document carries its own reason in its revision history; a change of people is a line on FRM-009; the form went from 20 fields to 12.\n\nBUILT ON WHAT EXISTS: FSQM-017 Part 4 (assess before the change), FSQM-004 (a cover for every key position), FSQM-005 and FRM-001 (the yearly review).\n\nNo verification schedule row: a change is assessed when it happens.\n\nAT ISSUE: revise FSQM-017 Part 4 to name FSQM-007 and FRM-015 in place of its interim rule; revise SOP-2.3.1 so that \"the Management of Change Procedure\" reads FSQM-007.\n\nTO CONFIRM BEFORE ISSUE: the first real change recorded on FRM-015."}$q$::jsonb end
 where d.sop_number = 'FSQM-007' and d.status = 'draft';

update public.sop_documents d
   set content = case when d.content ? 'attachments' then jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{change_type} - {raised_on}"}, "sections": [{"id": "change", "title": "1. The change", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "Only for a new product or a recipe change, a change to a process step or a limit, or new or modified equipment that touches the product (FSQM-007). A label, a supplier, a material, a procedure or a change of staff is NOT recorded here. Fill it in and have it approved BEFORE the change is made."}, {"id": "change_type", "type": "select", "label": "Kind of change", "width": "third", "required": true, "showInList": true, "options": ["New product or recipe", "Process step or limit", "Equipment"]}, {"id": "raised_on", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true}, {"id": "description", "type": "textarea", "label": "What is changing", "required": true, "showInList": true, "help": "From what, to what; which product, step or machine; and what changes in the process - steps, times, temperatures, cleaning"}, {"id": "reason", "type": "textarea", "label": "Reason for the change", "required": true}]}, {"id": "assessment", "title": "2. Assessment", "fields": [{"id": "questions", "type": "grid", "label": "Five questions", "required": true, "columns": [{"id": "answer", "label": "Answer", "type": "select", "options": ["Yes", "No"], "required": true, "width": 0.8}, {"id": "needed", "label": "If yes: what is done before the change", "type": "text", "width": 3, "scanFact": "none"}], "rows": {"mode": "fixed", "labels": ["Does it change a hazard, a CCP or a limit in the food safety plan (FSQM-016)?", "Does it change the process flow, or what keeps unbaked from baked and nuts from products without them?", "Does it change the allergens or the label?", "Does a specification, a cleaning procedure or another document need revising?", "Does anyone need to be told or trained before it starts?"], "labelHeader": "Question"}}, {"id": "validation", "type": "textarea", "label": "How the change was shown to be safe", "required": true, "help": "A trial, a measurement, the maker's specification, or a regulatory standard. Say which, and attach it."}]}, {"id": "decision", "title": "3. Decision", "fields": [{"id": "decision", "type": "select", "label": "Decision", "width": "third", "required": true, "showInList": true, "options": ["Approved", "Approved with conditions", "Not approved"]}, {"id": "effective_on", "type": "date", "label": "Takes effect on", "width": "third"}, {"id": "told", "type": "textarea", "label": "Who was told or trained, and when", "help": "Also write any condition of the approval here"}, {"id": "assessed_by", "type": "signature", "label": "Assessed by", "role": "filler", "required": true, "statement": "I assessed this change before it was made."}, {"id": "approved_by", "type": "signature", "label": "Approved by Senior Site Management", "role": "verifier", "required": true, "statement": "I approve this change on the assessment above."}]}]}$q$::jsonb) || jsonb_build_object('attachments', d.content->'attachments') else jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{change_type} - {raised_on}"}, "sections": [{"id": "change", "title": "1. The change", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "Only for a new product or a recipe change, a change to a process step or a limit, or new or modified equipment that touches the product (FSQM-007). A label, a supplier, a material, a procedure or a change of staff is NOT recorded here. Fill it in and have it approved BEFORE the change is made."}, {"id": "change_type", "type": "select", "label": "Kind of change", "width": "third", "required": true, "showInList": true, "options": ["New product or recipe", "Process step or limit", "Equipment"]}, {"id": "raised_on", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true}, {"id": "description", "type": "textarea", "label": "What is changing", "required": true, "showInList": true, "help": "From what, to what; which product, step or machine; and what changes in the process - steps, times, temperatures, cleaning"}, {"id": "reason", "type": "textarea", "label": "Reason for the change", "required": true}]}, {"id": "assessment", "title": "2. Assessment", "fields": [{"id": "questions", "type": "grid", "label": "Five questions", "required": true, "columns": [{"id": "answer", "label": "Answer", "type": "select", "options": ["Yes", "No"], "required": true, "width": 0.8}, {"id": "needed", "label": "If yes: what is done before the change", "type": "text", "width": 3, "scanFact": "none"}], "rows": {"mode": "fixed", "labels": ["Does it change a hazard, a CCP or a limit in the food safety plan (FSQM-016)?", "Does it change the process flow, or what keeps unbaked from baked and nuts from products without them?", "Does it change the allergens or the label?", "Does a specification, a cleaning procedure or another document need revising?", "Does anyone need to be told or trained before it starts?"], "labelHeader": "Question"}}, {"id": "validation", "type": "textarea", "label": "How the change was shown to be safe", "required": true, "help": "A trial, a measurement, the maker's specification, or a regulatory standard. Say which, and attach it."}]}, {"id": "decision", "title": "3. Decision", "fields": [{"id": "decision", "type": "select", "label": "Decision", "width": "third", "required": true, "showInList": true, "options": ["Approved", "Approved with conditions", "Not approved"]}, {"id": "effective_on", "type": "date", "label": "Takes effect on", "width": "third"}, {"id": "told", "type": "textarea", "label": "Who was told or trained, and when", "help": "Also write any condition of the approval here"}, {"id": "assessed_by", "type": "signature", "label": "Assessed by", "role": "filler", "required": true, "statement": "I assessed this change before it was made."}, {"id": "approved_by", "type": "signature", "label": "Approved by Senior Site Management", "role": "verifier", "required": true, "statement": "I approve this change on the assessment above."}]}]}$q$::jsonb) end
 where d.sop_number = 'FRM-015' and d.status = 'draft';

do $verify$
declare p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-007';
  if jsonb_array_length(p) <> 29 then raise exception 'FSQM-007 procedure is % lines, expected 29.', jsonb_array_length(p); end if;
  if (select count(*) from unnest(array['2.1.1.7)', '2.2.1.2)', '2.3.1.4)', '2.3.1.5)']) c where p::text like '%' || c || '%') <> 4 then
    raise exception 'FSQM-007 does not cite every clause it closes.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-007', 'FRM-015')
              and content::text ~* 'Diana|Gabriela|Christina|GJM|Mercer|Pillsbury|Amazon|Sysco|Bahamas') then
    raise exception 'a D-04 document names a person, a supplier or a customer.';
  end if;
  if (select count(*) from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
                           jsonb_array_elements(s->'fields') f where d.sop_number = 'FRM-015') <> 12 then
    raise exception 'FRM-015 field count is wrong.';
  end if;
end $verify$;

commit;
